"""Standalone HTML for the manual investment module workspace."""

from __future__ import annotations


MODULE_DASHBOARD_HTML = r"""<!doctype html>
<html lang="zh-CN">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="icon" href="data:,">
<title>投资工作台</title>
<style>
:root{--nav:#0b1f38;--nav2:#102b4d;--blue:#1769e0;--blue2:#eaf2ff;--ink:#172236;--muted:#68778d;--bg:#f4f7fb;--card:#fff;--line:#dfe6ef;--green:#087b5b;--greenbg:#e8f6f0;--amber:#9a5b00;--amberbg:#fff5dd;--red:#b42318;--redbg:#fff0ee;--shadow:0 8px 28px rgba(19,40,70,.07)}
*{box-sizing:border-box}html{height:100%}body{margin:0;min-height:100%;background:var(--bg);color:var(--ink);font:14px/1.55 system-ui,-apple-system,"Segoe UI","Microsoft YaHei",sans-serif;font-variant-numeric:tabular-nums}.app{min-height:100vh;display:grid;grid-template-columns:252px minmax(0,1fr)}aside{position:sticky;top:0;height:100vh;background:linear-gradient(180deg,var(--nav),#07172a);color:#d7e3f2;padding:25px 18px;display:flex;flex-direction:column}.brand{padding:0 10px 24px;border-bottom:1px solid #ffffff18}.brand strong{display:block;color:white;font-size:19px;letter-spacing:.04em}.brand small{color:#90a7c1}.navtitle{margin:24px 10px 8px;color:#7891ad;font-size:11px;letter-spacing:.14em}.navbtn{width:100%;border:0;background:transparent;color:#bdd0e4;text-align:left;padding:12px;border-radius:10px;cursor:pointer;margin:3px 0}.navbtn:hover,.navbtn.active{background:#ffffff12;color:#fff}.navbtn.active{box-shadow:inset 3px 0 #5ca0ff}.navbtn b{display:block;font-size:14px}.navbtn span{font-size:12px;color:#829ab5}.legacy{margin-top:auto;color:#bdd0e4;text-decoration:none;padding:12px;border:1px solid #ffffff22;border-radius:10px;text-align:center}.legacy:hover{background:#ffffff0d}main{min-width:0;padding:28px 32px 50px}.top{display:flex;justify-content:space-between;gap:24px;align-items:flex-start;margin-bottom:22px}.eyebrow{color:var(--blue);font-weight:700;font-size:12px;letter-spacing:.08em}.top h1{font-size:27px;margin:3px 0 4px}.subtitle{color:var(--muted)}.asof{text-align:right;color:var(--muted);font-size:12px}.actions{display:flex;gap:9px;flex-wrap:wrap;justify-content:flex-end;margin-top:10px}button{font:inherit;border:0;border-radius:9px;padding:9px 14px;cursor:pointer;font-weight:650;background:var(--blue);color:white}button:hover{filter:brightness(.96)}button:disabled{opacity:.5;cursor:not-allowed}.secondary{background:#e9eef5;color:#29425f}.quiet{background:white;color:#37516e;border:1px solid var(--line)}.grid{display:grid;grid-template-columns:repeat(12,minmax(0,1fr));gap:16px}.card{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:19px;box-shadow:var(--shadow);min-width:0}.s3{grid-column:span 3}.s4{grid-column:span 4}.s5{grid-column:span 5}.s7{grid-column:span 7}.s8{grid-column:span 8}.s12{grid-column:span 12}.cardhead{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;margin-bottom:13px}.card h2{font-size:16px;margin:0}.card h3{font-size:14px;margin:16px 0 8px}.label{font-size:12px;color:var(--muted)}.metric{font-size:25px;font-weight:750;margin-top:3px}.pill{display:inline-flex;align-items:center;border-radius:99px;padding:3px 9px;font-size:12px;background:#edf1f6;color:#40546e}.pill.ok{background:var(--greenbg);color:var(--green)}.pill.warn{background:var(--amberbg);color:var(--amber)}.pill.bad{background:var(--redbg);color:var(--red)}.fact{border-left:3px solid var(--green);padding-left:10px}.plan{border-left:3px solid var(--blue);padding-left:10px}.muted{color:var(--muted)}.notice{border-radius:10px;padding:11px 13px;background:var(--blue2);color:#264a79}.notice.warn{background:var(--amberbg);color:#704600}.notice.bad{background:var(--redbg);color:var(--red)}.progress{height:8px;background:#e7edf5;border-radius:9px;overflow:hidden;margin:11px 0}.progress i{display:block;height:100%;background:linear-gradient(90deg,#1769e0,#68a5ff);transition:width .3s}.progress.running i{width:34%!important;animation:run 1.25s ease-in-out infinite}@keyframes run{0%{transform:translateX(-110%)}100%{transform:translateX(310%)}}.empty{text-align:center;padding:30px 16px;border:1px dashed #cdd7e5;border-radius:11px;color:var(--muted)}.empty svg{display:block;margin:0 auto 8px;color:#91a4ba}.scroll{overflow:auto}table{width:100%;border-collapse:collapse;min-width:720px}th,td{padding:11px 9px;border-bottom:1px solid var(--line);text-align:left;vertical-align:top}th{color:var(--muted);font-size:12px;font-weight:600}td.num{text-align:right}.symbol{font-weight:750}.name{font-size:12px;color:var(--muted)}details{border:1px solid var(--line);border-radius:10px;background:#fafbfd;margin:8px 0}summary{list-style:none;cursor:pointer;padding:11px 13px;font-weight:650}summary::-webkit-details-marker{display:none}summary:after{content:'展开';float:right;color:var(--blue);font-size:12px}details[open] summary:after{content:'收起'}details>div{border-top:1px solid var(--line);padding:12px 13px}.chips{display:flex;gap:6px;flex-wrap:wrap}.chip{background:#eef2f7;border-radius:5px;padding:2px 6px;font-size:12px}.agents{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.agent{border:1px solid var(--line);border-radius:11px;padding:13px}.agenttop{display:flex;justify-content:space-between;gap:8px}.agent p{margin:7px 0}.finding{padding:7px 9px;background:#f5f7fa;border-radius:7px;margin-top:6px}.decision{background:linear-gradient(135deg,#0d2745,#163d6b);color:white;border:0}.decision .muted{color:#b9cbe0}.decision table{color:#fff}.decision th,.decision td{border-color:#ffffff20}.decision th{color:#b9cbe0}.price{white-space:nowrap;font-weight:700}.good{color:var(--green)}.badtext{color:var(--red)}.bar{height:18px;display:flex;background:#e8edf4;border-radius:7px;overflow:hidden}.bar span{height:100%;min-width:1px}.legend{display:flex;gap:13px;flex-wrap:wrap;margin-top:9px;font-size:12px}.dot{width:8px;height:8px;display:inline-block;border-radius:50%;margin-right:5px}.legs{display:grid;grid-template-columns:1fr 40px 1fr;align-items:stretch;gap:10px}.leg{border:1px solid #ffffff30;border-radius:10px;padding:12px}.arrow{display:grid;place-items:center;font-size:22px}.scenario{display:grid;grid-template-columns:repeat(3,1fr);gap:9px}.scenario>div{border:1px solid var(--line);border-radius:10px;padding:11px}.scenario b{display:block;margin-bottom:4px}.accountform{display:grid;grid-template-columns:repeat(6,1fr);gap:8px}.accountform input{width:100%;border:1px solid var(--line);border-radius:8px;padding:9px}.accountform .wide{grid-column:span 2}.formactions{margin-top:10px;display:flex;justify-content:flex-end}.toast{position:fixed;right:22px;bottom:22px;max-width:380px;background:#15253a;color:white;border-radius:10px;padding:12px 16px;box-shadow:0 12px 40px #0004;z-index:5}.hidden{display:none!important}.detailraw{white-space:pre-wrap;word-break:break-word;font:12px/1.5 ui-monospace,Consolas,monospace;max-height:300px;overflow:auto}dialog{width:min(720px,94vw);border:0;border-radius:14px;padding:0;box-shadow:0 24px 80px #10203055}dialog::backdrop{background:#07172a88}.dialoghead{background:var(--nav);color:white;padding:15px 18px;display:flex;justify-content:space-between}.dialogbody{padding:18px;max-height:75vh;overflow:auto}.dialoghead button{padding:4px 9px;background:#ffffff18}
@media(max-width:1000px){.app{grid-template-columns:210px auto}main{padding:22px 18px}.s3,.s4{grid-column:span 6}.s5,.s7,.s8{grid-column:span 12}}
@media(max-width:700px){.app{display:block}aside{position:static;height:auto;padding:14px}.brand{padding:0 4px 10px}.navtitle{display:none}nav{display:flex;overflow:auto;gap:6px;margin-top:8px}.navbtn{min-width:145px;margin:0}.navbtn span{display:none}.legacy{display:block;margin-top:10px;padding:8px}.top{display:block}.asof{text-align:left;margin-top:12px}.actions{justify-content:flex-start}.s3,.s4,.s5,.s7,.s8,.s12{grid-column:span 12}.card{padding:15px}.agents,.scenario{grid-template-columns:1fr}.legs{grid-template-columns:1fr}.arrow{transform:rotate(90deg)}.accountform{grid-template-columns:1fr 1fr}.accountform .wide{grid-column:span 1}main{padding:18px 12px 36px}.top h1{font-size:23px}}
.positionrow{display:grid;grid-template-columns:1.1fr 1.4fr 1fr 1fr 1fr auto;gap:8px;margin-top:8px}.positionrow input{width:100%;min-width:0;border:1px solid var(--line);border-radius:8px;padding:9px}.positionrow button{padding:8px 11px}.formactions{gap:8px}.notice{overflow-wrap:anywhere;word-break:break-word}@media(max-width:700px){.positionrow{grid-template-columns:1fr 1fr}.positionrow button{grid-column:span 2}}
.decision .chip{background:#ffffff18;color:#fff}.decision .name{color:#b9cbe0}.decision details{background:#ffffff0a;border-color:#ffffff30}.decision details summary:after{color:#9fc9ff}.valuation-company{margin-top:18px;padding-top:10px;border-top:1px solid #ffffff30}.valuation-quote{margin:10px 0;padding:10px;border:1px solid #ffffff30;border-radius:8px}
</style></head>
<body><div class="app"><aside><div class="brand"><strong>投资工作台</strong><small>研究、规划与账户事实</small></div><div class="navtitle">独立策略模块</div><nav id="moduleNav"><button class="navbtn active" data-module="value"><b>价值投资</b><span>基本面与估值</span></button><button class="navbtn" data-module="closing"><b>尾盘隔夜</b><span>收盘前决策</span></button><button class="navbtn" data-module="etf"><b>ETF 动态仓位 / 做 T</b><span>10 万元规划</span></button></nav><a class="legacy" href="/legacy">返回原缠论系统 →</a></aside>
<main><header class="top"><div><div class="eyebrow">MANUAL RESEARCH DESK</div><h1 id="title">正在读取模块…</h1><div id="subtitle" class="subtitle">每次扫描与讨论均由你手动启动</div></div><div><div class="asof" id="asof">数据时点：—</div><div class="actions"><button class="quiet" id="refreshBtn">刷新状态</button><button class="secondary hidden" id="quickBtn">快速检查最新行情</button><button class="secondary" id="experimentBtn">扩展研究（下一批）</button><button id="scanBtn">扫描候选（较慢）</button><button id="analyzeBtn">开始 Agent 讨论（更慢）</button></div></div></header>
<div id="error" class="notice bad hidden"></div><section id="workspace" class="grid" aria-live="polite"><div class="card s12"><div class="empty">正在读取真实数据…</div></div></section></main></div>
<div id="toast" class="toast hidden"></div><dialog id="rawDialog"><div class="dialoghead"><b>详细证据</b><button onclick="document.querySelector('#rawDialog').close()">关闭</button></div><div class="dialogbody" id="rawBody"></div></dialog>
<script>
const S={id:'value',detail:null,poll:null};
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const api=async(url,options)=>{const r=await fetch(url,options);let body={};try{body=await r.json()}catch{}if(!r.ok)throw Error(body.error||body.message||`请求失败（${r.status}）`);return body};
const money=v=>v==null?'—':'¥'+Number(v).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2});
const pct=v=>v==null?'—':(Number(v)*100).toFixed(1)+'%';
const price=(v,id=S.id)=>v==null?'—':Number(v).toFixed(id==='etf'?3:2);
const time=v=>v?String(v).replace('T',' ').replace(/Z$/,''):'—';
const TERM={bond_or_money_buy_excluded_by_user:'用户禁止配置债券及货币类ETF',government_bond_related_buy_excluded_by_user:'用户排除国债及政府债相关产品',duplicate_tracking_index:'跟踪同一指数，保留更优代表',turnover_below_10m_cny:'成交额低于 1000 万元',turnover_below_threshold:'成交额未达门槛',insufficient_liquidity:'流动性不足',insufficient_history:'历史数据不足',listing_too_recent:'上市时间较短',price_unavailable:'最新价格不可用',tracking_index_unknown:'跟踪指数未知',same_day_turnaround_unknown:'当日回转属性未知',not_same_day_turnaround:'不支持当日回转',scale_below_threshold:'基金规模未达门槛',spread_too_wide:'买卖价差过大',data_incomplete:'关键数据不完整'};
const term=x=>TERM[String(x)]||String(x??'—');
const readable=x=>{if(x==null)return '—';if(typeof x!=='object')return String(x);if(Array.isArray(x))return x.map(readable).join('；');const value=v=>typeof v==='object'?readable(v):String(v);const preferred=['title','name','summary','claim','finding','text','url','source','reason','detail','conclusion'];const parts=preferred.filter(k=>x[k]!=null&&x[k]!=='').map(k=>`${k==='url'?'链接：':k==='source'?'来源：':''}${value(x[k])}`);if(parts.length)return parts.join(' · ');return Object.entries(x).map(([k,v])=>`${k}：${value(v)}`).join(' · ')||'结构化记录（请在详细证据中查看）'};
const list=(xs,empty='暂无')=>(xs&&xs.length)?'<ul>'+xs.map(x=>'<li>'+esc(typeof x==='string'?term(x):readable(x))+'</li>').join('')+'</ul>':'<span class="muted">'+empty+'</span>';
const safeUrl=u=>{try{const x=new URL(String(u));return ['http:','https:'].includes(x.protocol)?x.href:null}catch{return null}};
const sources=xs=>(xs&&xs.length)?'<ul>'+xs.map(x=>{if(typeof x==='string')return `<li>${esc(term(x))}</li>`;const url=safeUrl(x.url),title=x.title||x.name||x.source||x.metadata?.title||x.metadata?.source||'数据来源',meta=[x.publisher,x.as_of_time,x.date].filter(Boolean).join(' · ');return `<li>${url?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(title)}</a>`:`${esc(title)}`}${meta?` <span class="muted">${esc(meta)}</span>`:''}</li>`}).join('')+'</ul>':'<span class="muted">未提供来源</span>';
function toast(msg){const e=$('#toast');e.textContent=msg;e.classList.remove('hidden');setTimeout(()=>e.classList.add('hidden'),3500)}
function empty(title,tip){return `<div class="empty"><svg width="34" height="34" viewBox="0 0 24 24" fill="none" stroke="currentColor"><path d="M4 19V8m5 11V4m5 15v-7m5 7V6"/><path d="M2 19h20"/></svg><b>${esc(title)}</b><div>${esc(tip)}</div></div>`}
function statusPill(v){const map={completed:['已完成','ok'],running:['运行中','warn'],pending:['等待中',''],queued:['排队中',''],paused:['已暂停','warn'],failed:['失败','bad'],idle:['未运行',''],insufficient_history:['样本不足','warn'],completed_with_warnings:['完成，有警告','warn']};const x=map[v]||[v||'未运行',''];return `<span class="pill ${x[1]}">${esc(x[0])}</span>`}
function targetExposureCard(d){
 const m=d.module||{};if(S.id!=='etf')return {label:'目标仓位',value:m.target_exposure,detail:'规划上限，须经本轮决策确认'};
 const a=d.analysis||{},dec=a.decision||{},allocation=dec.allocation||{},ex=a.execution||{};
 const value=allocation.target_investment_ratio??dec.target_investment_ratio;
 if(value==null)return {label:'目标仓位',value:null,detail:'等待本轮研究给出目标仓位'};
 const expired=(dec.positions||[]).map(p=>p.expires_at).some(x=>x&&Number.isFinite(Date.parse(x))&&Date.parse(x)<=Date.now());
 const quoteExpired=ex.quote_valid_until&&Number.isFinite(Date.parse(ex.quote_valid_until))&&Date.parse(ex.quote_valid_until)<=Date.now();
 const replaced=(d.scan?.scan_id&&a.scan_id!==d.scan.scan_id)||ex.status==='account_changed';
 const state=expired||replaced?'历史研究目标 · 需更新核验':dec.status==='approve'?'本轮条件研究目标':'未批准研究草案';
 return {label:'研究目标仓位',value,detail:state+(allocation.investment_ratio==null?'':` · 整手后 ${pct(allocation.investment_ratio)}`)+(quoteExpired?' · 执行报价需刷新':'')};
}
function accountCards(d){const a=d.account||{},m=d.module||{},exposure=targetExposureCard(d);const confirmed=a.cash_confirmed===true,positionsConfirmed=S.id==='value'||a.positions_confirmed===true;return `<div class="card s3 plan"><div class="label">规划预算</div><div class="metric">${money(m.budget??a.budget)}</div><div class="muted">用于方案测算，不代表已入金</div></div><div class="card s3 fact"><div class="label">已确认可用现金</div><div class="metric">${confirmed?money(a.cash):'待确认'}</div><div class="muted">${confirmed?'账户事实 · 版本 '+esc(a.version||'—'):'请按券商账户录入事实'}</div></div><div class="card s3"><div class="label">${esc(exposure.label)}</div><div class="metric">${pct(exposure.value)}</div><div class="muted">${esc(exposure.detail)}</div></div><div class="card s3"><div class="label">实际持仓</div><div class="metric">${positionsConfirmed?(a.positions||[]).length+' 项':'待确认'}</div><div class="muted">${positionsConfirmed?'账户模式：'+esc(a.mode||m.account_mode||'—'):'尚未确认券商持仓事实'}</div></div>`}
function moduleBusy(d){return [d.task,d.analysis].some(x=>x&&['running','queued','pending'].includes(x.status))}
function taskCard(t,d={}){if(!t)return '';const taskTime=Date.parse(t.completed_at||t.started_at||t.created_at),newestTime=Math.max(...[d.analysis?.started_at,d.scan?.as_of_time,d.refresh?.checked_at,d.experiment?.started_at].map(x=>Date.parse(x)).filter(Number.isFinite));const active=['running','queued','pending'].includes(t.status),historical=!active&&Number.isFinite(taskTime)&&newestTime>taskTime;const title=historical?'历史任务':active?'本次任务':'最近任务记录';const total=Number(t.total)||0,done=Number(t.completed)||0,p=total?Math.min(100,done/total*100):(t.status==='completed'?100:0);return `<div class="card s12"><div class="cardhead"><div><h2>${title}</h2><div class="muted">${esc(t.phase||'阶段未标注')}</div><div class="muted">任务时间 ${esc(time(t.started_at||t.created_at))}${historical?' · 已有更新扫描或研究，此状态不代表当前研究':''}</div></div>${statusPill(t.status)}</div><div class="progress ${t.status==='running'&&!total?'running':''}"><i style="width:${p}%"></i></div><div class="muted">${total?`${done} / ${total} 个阶段`:t.status==='running'?'任务正在后台执行，请保留页面':'阶段进度尚未生成'}</div>${t.error?`<details><summary>查看失败原因</summary><div class="notice bad">${esc(t.error)}</div></details>`:''}</div>`}
function primaryReason(c){const raw=(c.reasons||[])[0]||(c.evidence_gaps||[])[0];return raw?term(typeof raw==='object'?readable(raw):raw):(c.eligible?'规模、流动性等初筛通过':'查看未通过条件')}
function candidateRows(scan){return (scan.candidates||[]).map((c,i)=>`<tr><td><span class="symbol">${esc(c.symbol)}</span><div class="name">${esc(c.name||'')}</div></td><td class="num">${price(c.price)}</td><td class="num">${c.score==null?'—':Number(c.score).toFixed(1)}</td><td>${c.eligible===false?'<span class="pill bad">未通过</span>':'<span class="pill ok">可研究</span>'}</td><td>${esc(primaryReason(c))}</td><td><button class="quiet" onclick="showCandidate(${i})">展开证据</button></td></tr>`).join('')}
function scanCard(scan){if(!scan)return `<div class="card s12"><div class="cardhead"><h2>候选扫描</h2><span class="pill">尚未扫描</span></div>${empty('还没有候选数据','点击“扫描候选”后，此处显示真实筛选结果。扫描不会自动开始 Agent 讨论。')}</div>`;const q=scan.quality||{};return `<div class="card s12"><div class="cardhead"><div><h2>扫描候选</h2><div class="muted">扫描 ${Number(scan.universe_count||0).toLocaleString('zh-CN')} 个标的 · 数据截至 ${time(scan.as_of_time)}</div></div>${statusPill(q.status==='failed'?'failed':'completed')}</div>${(q.warnings||[]).length?`<div class="notice warn">${esc(q.warnings.join('；'))}</div>`:''}<div class="scroll"><table><thead><tr><th>代码 / 名称</th><th>扫描时价格</th><th>评分</th><th>资格</th><th>首要依据</th><th>证据</th></tr></thead><tbody>${candidateRows(scan)||`<tr><td colspan="6">${empty('本轮没有合格候选','查看数据质量后，可在新的数据时点重新扫描。')}</td></tr>`}</tbody></table></div><details><summary>方法与数据来源</summary><div><h3>筛选方法</h3>${list(scan.methodology,'未提供方法说明')}<h3>来源</h3>${sources(scan.sources)}</div></details></div>`}
function agentsCard(a){if(!a)return `<div class="card s12"><div class="cardhead"><h2>Agent 讨论与证据分歧</h2><span class="pill">尚未讨论</span></div>${empty('扫描与讨论彼此独立','先完成一次候选扫描，再点击“开始 Agent 讨论”。')}</div>`;const rs=a.research||[];return `<div class="card s12"><div class="cardhead"><div><h2>Agent 讨论与证据分歧</h2><div class="muted">研究数据截至 ${time(a.as_of_time)}${a.started_at?` · 研究启动 ${esc(time(a.started_at))}`:''}</div></div>${statusPill(a.status)}</div><div class="agents">${rs.map((x,i)=>`<div class="agent"><div class="agenttop"><b>${esc(x.display_name||x.agent_id)}</b>${statusPill(x.status)}</div><div class="muted">${esc(x.model||'模型未标注')}</div><p>${esc(x.summary||'尚无摘要')}</p><details><summary>发现与分歧</summary><div>${list(x.findings,'暂无结构化发现')}<button class="quiet" onclick="showAgent(${i})">查看完整证据</button></div></details></div>`).join('')||empty('尚无 Agent 输出','任务开始后，这里按角色逐项更新。')}</div></div>`}
function positionQuantity(p){const unit=S.id==='etf'?'份':'股',current=p.current_quantity==null?'未知':Number(p.current_quantity).toLocaleString('zh-CN'),target=p.target_quantity??p.quantity??p.theoretical_target_quantity,targetText=target==null?'未知':Number(target).toLocaleString('zh-CN'),minimum=p.minimum_required_cash_cny==null?'':`<div class="name">最低交易单位所需资金 ${money(p.minimum_required_cash_cny)}</div>`;if(p.delta_quantity==null)return `<b>预算目标 ${targetText} ${unit}</b><div class="name">当前 ${current} · 调仓差额待账户核验</div>${minimum}`;if(S.id==='etf')return `${targetText} 份`;const delta=Number(p.delta_quantity),theoretical=p.theoretical_target_quantity;return `<b>拟新增 ${delta.toLocaleString('zh-CN')} 股</b><div class="name">当前 ${current} → 情景持仓 ${targetText} 股${theoretical!=null?` · 理论目标 ${Number(theoretical).toLocaleString('zh-CN')} 股`:''}</div>${minimum}`}
function priceComparison(p,a){const row=(a.price_comparison?.rows||[]).find(x=>x.symbol===p.symbol);if(!row)return '<span class="muted">未提供参考报价及时间，无法比较；目标买入价不是现价。</span>';const relation={above_entry:'参考报价高于目标区间',below_entry:'参考报价低于目标区间，需重新核验',within_entry:'参考报价位于目标区间，仍需满足其余条件',unknown:'报价不可比较'}[row.relation]||'报价不可比较';return `<b>${row.reference_price==null?'未提供参考报价':`已采集参考报价 ${price(row.reference_price)}（非实时）`}</b><div class="name">报价时间 ${esc(row.reference_at?time(row.reference_at):'未提供')} · 来源 ${esc(row.reference_source||'未提供')}</div>${row.reference_stale?'<div class="notice warn">参考报价已过期，需刷新核验</div>':''}<div>${esc(relation)}</div><div>目标上限相对参考报价 ${row.gap_to_entry_max==null?'未提供':pct(row.gap_to_entry_max)}</div><div class="name">研究时报价 ${row.research_price==null?'未提供':price(row.research_price)} · ${esc(row.research_at?time(row.research_at):'未提供')}</div>`}
function positions(dec,a){return (dec.positions||[]).map(p=>`<tr><td><b>${esc(p.symbol)}</b><div class="name">${esc(p.name||'')}</div></td><td>${pct(p.target_weight)}</td><td>${positionQuantity(p)}</td><td class="price">${price(p.entry_min)} – ${price(p.entry_max)}</td><td>${priceComparison(p,a)}</td><td class="price">${price(p.take_profit)} / ${price(p.stop_loss)}</td><td>${esc(p.expires_at||'—')}</td><td>${esc(p.reason||'—')}</td></tr>`).join('')}
const TSTATUS={awaiting_reconciliation:'等待调仓成交对账',ready:'计划可用',ineligible:'条件未满足'};
function tPlan(t){const legs=t.legs||[];const body=legs.length?`<div class="legs">${legs.map((leg,i)=>`${i?'<div class="arrow">→</div>':''}<div class="leg"><b>第 ${i+1} 腿 · ${esc(leg.side==='buy'?'买入':leg.side==='sell'?'卖出':leg.side||'未指定')}</b><div>${Number(leg.quantity||0).toLocaleString('zh-CN')} 份 · 限价 ${price(leg.limit_price)}</div><div class="muted">库存依据：${esc(leg.inventory_basis||'未提供')}</div></div>`).join('')}</div>`:`<div class="notice">条件未满足：${esc((t.reasons||[]).map(readable).join('；')||'未提供原因')}</div>`;const guard=legs.length?`<div class="notice warn"><b>开仓前确认：</b>止盈 ${price(t.take_profit)} · 止损 ${price(t.stop_loss)} · 有效至 ${esc(t.expires_at||'未标注')}</div><div>${esc(t.reason||'未提供计划理由')}</div>`:'',reconcile=t.status==='awaiting_reconciliation'?'<div class="notice warn">同一标的的调仓需先完成成交并对账，再按最新持仓重新计算做 T 计划。</div>':'';return `<details open><summary>${esc(t.symbol||'ETF')} · ${esc(TSTATUS[t.status]||t.status||'状态未标注')}</summary><div>${reconcile}${guard}${body}<div class="muted">预计净收益边际：${money(t.estimated_net_edge_cny)}</div>${legs.length&&t.reasons&&t.reasons.length?list(t.reasons):''}</div></details>`}
function rebalanceDetails(dec){const rows=(dec.positions||[]).map(p=>{const delta=p.delta_quantity==null?null:Number(p.delta_quantity),current=p.current_quantity==null?'未知':Number(p.current_quantity).toLocaleString('zh-CN'),target=p.target_quantity??p.quantity,targetText=target==null?'未知':Number(target).toLocaleString('zh-CN');const action=delta===null?'待账户核验':delta>0?`买入 ${delta.toLocaleString('zh-CN')}`:delta<0?`卖出 ${Math.abs(delta).toLocaleString('zh-CN')}`:'无需调整';return `<tr><td><b>${esc(p.symbol)}</b><div class="name">${esc(p.name||'')}</div></td><td>${current} → ${delta===null?'预算目标 ':''}${targetText}</td><td>${action}</td></tr>`}).join('');return `<details><summary>拟调仓明细</summary><div><div class="chips"><span class="chip">资金口径 ${esc(dec.capital_basis||'未标注')}</span><span class="chip">当前 NAV ${dec.current_nav_cny==null?'待账户核验':money(dec.current_nav_cny)}</span><span class="chip">名义目标仓位 ${pct(dec.target_investment_ratio)}</span><span class="chip">整手后规划仓位 ${pct(dec.investment_ratio)}</span><span class="chip">现金预留 ${money(dec.cash_reserve_cny)}</span></div>${dec.cash_contingent_on_sales?'<div class="notice warn">买入资金依赖先完成计划卖出；卖出未成交前不要提前占用这部分现金。</div>':''}<div class="scroll"><table><thead><tr><th>标的</th><th>当前 → 目标</th><th>本次买卖差额</th></tr></thead><tbody>${rows||'<tr><td colspan="3">没有需要调整的持仓。</td></tr>'}</tbody></table></div></div></details>`}
function regionExposure(dec){const names={a_share:'A股',hong_kong:'港股',us:'美股',japan:'日本',europe:'欧洲',india:'印度',mixed:'混合市场',unknown:'地区待核验',gold:'黄金',excluded:'禁投资产'};const rows=Object.entries(dec.allocation?.regional_exposure||{});return rows.length?`<h3>底层市场配置</h3><div class="chips">${rows.map(([k,v])=>`<span class="chip">${esc(names[k]||k)} ${pct(v)}</span>`).join('')}</div>`:''}
function etfSpecial(dec){const ps=dec.positions||[],colors=['#4385e8','#25a780','#f0a33c','#8a6ddb','#8391a4'];const bar=ps.map((p,i)=>`<span style="width:${Number(p.target_weight||0)*100}%;background:${colors[i%colors.length]}" title="${esc(p.symbol)} ${pct(p.target_weight)}"></span>`).join('')+`<span style="width:${Number(dec.cash_weight||0)*100}%;background:#cbd5e1"></span>`;const legend=ps.map((p,i)=>`<span><i class="dot" style="background:${colors[i%colors.length]}"></i>${esc(p.symbol)} ${pct(p.target_weight)}</span>`).join('')+`<span><i class="dot" style="background:#cbd5e1"></i>现金 ${pct(dec.cash_weight)}</span>`;const ts=dec.t_plans||[];return `<h3>目标配置</h3><div class="bar">${bar}</div><div class="legend">${legend}</div>${regionExposure(dec)}${rebalanceDetails(dec.allocation||dec)}<h3>配置取舍与增减仓触发</h3>${list(dec.discussion_resolution,'本轮未提供配置触发条件')}<h3>下一交易日开盘条件计划</h3><div class="scenario">${[['high_open','高开'],['flat_open','平开'],['low_open','低开']].map(([key,label])=>`<div><b>${label}</b>${esc(dec.exit_plan?.[key]||'未提供条件计划')}</div>`).join('')}</div><h3>做 T 两腿计划</h3>${ts.length?ts.map(tPlan).join(''):`<div class="notice">本轮没有满足价差、流动性与可用份额条件的做 T 建议。</div>`}`}
function closingSpecial(dec){const e=dec.exit_plan||{};return `<h3>尾盘操作时窗</h3><div class="notice">${esc(dec.trading_window||'以本轮方案给出的尾盘有效时窗为准；过时不追单。')}</div><h3>次日开盘预案</h3><div class="scenario"><div><b>高开</b>${esc(e.high_open||'未给出高开预案')}</div><div><b>平开</b>${esc(e.flat_open||'未给出平开预案')}</div><div><b>低开</b>${esc(e.low_open||'未给出低开预案')}</div></div>`}
function supplementalCard(a){const rows=a?.supplemental_research||[];if(!rows.length)return '';return `<div class="card s12"><div class="cardhead"><h2>定向补证与复议</h2><span class="pill">${rows.filter(r=>r.status==='completed').length} / ${rows.length} 已完成</span></div><div class="notice">交叉质询提出具体缺口后进行一轮补证，结果交回组合和风控。仍未解决的问题保留，不自动当作通过。</div>${rows.map(r=>`<details><summary>${esc(r.display_name||r.agent_id)} · ${statusPill(r.status)}</summary><div><p>${esc(r.summary||r.error||'补证执行中')}</p><div class="detailraw">${esc(JSON.stringify(r,null,2))}</div></div></details>`).join('')}</div>`;}
function valuationEntry(v){if(v.entry_min!=null&&v.entry_max!=null)return `条件介入区间 ${price(v.entry_min)} – ${price(v.entry_max)}`;if(v.entry_max!=null)return `仅有观察上限 ${price(v.entry_max)} · 下限待补证`;return '介入区间待补证';}
function valuationResearch(d,a={}){if(S.id!=='value')return '';const vs=d.valuations||[];if(!vs.length)return '<h3>逐公司财务估值</h3><div class="notice">本轮未提供结构化财务估值；不能从买入区间反推合理价值。</div>';const methods={normalized_pe:'正常化盈利 PE',forward_pe:'预测盈利 PE',p_fcf:'每股自由现金流倍数',insufficient_evidence:'证据不足'};return `<section class="valuation-research"><h3>逐公司财务估值 · 独立研究</h3><div class="notice">以下为财报和市场定价情景，不代表已批准买单。预测业绩与估值倍数均为假设，入手条件仍需核验。</div>${vs.map(v=>{const expired=v.expires_at&&Number.isFinite(Date.parse(v.expires_at))&&Date.parse(v.expires_at)<=Date.now();return `<div class="valuation-company"><h3>${esc(v.symbol)} ${esc(v.name||'')}</h3><div class="muted">财报期 ${esc(v.report_period||'待核验')} · ${esc(methods[v.method]||v.method||'待核验')} · ${esc(v.basis||'口径待核验')}</div><div class="chips"><span class="chip">合理价值 ${price(v.fair_value_min)} – ${price(v.fair_value_max)}</span><span class="chip">安全边际 ${pct(v.margin_of_safety)}</span><span class="chip">${valuationEntry(v)}</span></div><div class="valuation-quote">${priceComparison(v,a)}</div><div class="scroll"><table><thead><tr><th>情景</th><th>每股盈利 / 自由现金流</th><th>估值倍数</th><th>合理价（每股指标 × 倍数）</th><th>假设与来源</th></tr></thead><tbody>${[['bear','熊'],['base','基准'],['bull','牛']].map(([key,label])=>{const x=v.scenarios?.[key]||{};return `<tr><td>${label}</td><td>${price(x.per_share_metric)}</td><td>${x.multiple==null?'—':esc(x.multiple)}</td><td>${price(x.fair_price)}</td><td>${esc(x.assumptions||'证据待补')}<div class="name">证据 ${esc((x.evidence_refs||[]).join('、')||'待补')}</div></td></tr>`}).join('')}</tbody></table></div><p>区间上限 = 基准合理价 × (1 − 安全边际)；下限须有独立估值情景依据，跌破后重新核验基本面。${esc(v.buy_condition||'尚无可核验入手条件')}</p><div>研究止盈 / 风险止损 ${price(v.take_profit)} / ${price(v.stop_loss)} · 有效至 ${esc(v.expires_at||'未确定')}${expired?' · 已过期，需重估':''}</div><div>失效条件：${esc(v.invalidation||'待补')}</div>${(v.evidence_gaps||[]).length?`<div class="notice warn">证据缺口：${esc(v.evidence_gaps.join('；'))}</div>`:''}</div>`}).join('')}</section>`}
function planningNotice(d){const plan=d.allocation||d;if(plan.capital_basis!=='planned_funding')return '';return `<div class="notice">数量按规划预算 ${money(plan.capital_cny)} 测算；账户净值、现金或持仓仍待核验，执行前须重新计算实际买卖差额。</div>`}
function decisionCard(a){const d=a&&a.decision;if(!d)return `<div class="card s12">${empty('尚未形成投资方案','完成 Agent 讨论后，此处展示仓位、目标买入价和退出计划。')}</div>`;const ex=a.execution||{},approved=d.status==='approve',expired=(d.positions||[]).map(p=>p.expires_at).some(x=>x&&Number.isFinite(Date.parse(x))&&Date.parse(x)<=Date.now()),quoteExpired=ex.quote_valid_until&&Number.isFinite(Date.parse(ex.quote_valid_until))&&Date.parse(ex.quote_valid_until)<=Date.now(),state=approved?'研究方案已批准':d.status==='defer'?'未批准 · 研究草案':'决策状态未确认 · 研究草案',execution=(expired?'历史方案 · 方案有效期已过，需重新核验':!approved?'尚未获得批准，不能作为当前买入指令':ex.status==='account_changed'?'账户已变更 · 需重新讨论':ex.status==='manual_review'&&!quoteExpired&&!(ex.blockers||[]).length?'执行条件已通过系统检查 · 待人工复核':'条件建议 · 执行条件尚未满足')+(quoteExpired?' · 执行报价需刷新':''),noPositions=S.id==='etf'?'尚未形成满足投资仓位要求的方案。':'本轮暂无建仓标的。';const details=`<div class="scroll"><table><thead><tr><th>标的</th><th>目标权重</th><th>${S.id==='etf'?'目标数量（非新增）':'持仓与拟新增数量'}</th><th>研究目标买入区间（不是现价）</th><th>报价对照</th><th>止盈 / 止损</th><th>有效至</th><th>理由</th></tr></thead><tbody>${positions(d,a)||`<tr><td colspan="8">${noPositions}</td></tr>`}</tbody></table></div>${S.id==='etf'?etfSpecial(d):''}${S.id==='closing'?closingSpecial(d):''}<h3>组合风险与退出</h3>${list(d.risks,'未列出额外风险')}<details><summary>完整退出计划</summary><div>${esc(readable(d.exit_plan||'未提供退出计划'))}</div></details>`;return `<div class="card s12 decision"><div class="cardhead"><div><h2>${approved?'条件投资方案':'研究草案'}</h2><div class="muted">研究截至 ${esc(time(a.as_of_time))} · 不代表已向券商下单</div></div><span class="pill ${approved?'ok':'warn'}">${state}</span></div><div class="notice warn"><b>${execution}</b><div>目标买入区间是研究设定的价格条件，不是当前市场报价。</div></div><p>${esc(d.summary||'')}</p><div class="muted">情景现金权重 ${pct(d.cash_weight)}</div>${valuationResearch(d,a)}${planningNotice(d)}${approved?details:`<details class="research-draft"><summary>展开未批准草案：目标价、情景仓位与退出条件</summary><div>${details}</div></details>`}</div>`}
function positionRow(p={}){return `<div class="positionrow" data-position><input data-field="symbol" placeholder="ETF 代码" value="${esc(p.symbol||'')}"><input data-field="name" placeholder="ETF 名称" value="${esc(p.name||'')}"><input data-field="quantity" type="number" step="1" min="0" placeholder="持有份额" value="${esc(p.quantity??'')}"><input data-field="available_quantity" type="number" step="1" min="0" placeholder="可用份额" value="${esc(p.available_quantity??'')}"><input data-field="cost_price" type="number" step="0.001" min="0" placeholder="成本价" value="${esc(p.cost_price??'')}"><button class="quiet" type="button" onclick="this.closest('[data-position]').remove()">删除</button></div>`}
function accountEditor(d){if(S.id!=='etf')return '';const a=d.account||{},rows=(a.positions||[]).map(positionRow).join('');return `<div class="card s12"><div class="cardhead"><div><h2>ETF 账户事实</h2><div class="muted">10 万元是规划预算。这里仅录入券商已经确认的现金和全部持仓。</div></div><span class="pill ${a.cash_confirmed?'ok':'warn'}">${a.cash_confirmed?'现金已确认':'待确认入金'}</span></div><div class="accountform"><input id="cash" type="number" required min="0" step="0.01" placeholder="券商可用现金（必填）" value="${esc(a.cash??'')}"></div><h3>实际持仓</h3><div id="positionRows">${rows}</div><div class="formactions"><button class="quiet" type="button" id="addPosition">＋ 添加持仓</button><button id="saveAccount">核对并保存账户事实</button></div></div>`}
const LIBSTATUS={usable:'可沿用',current:'可沿用',stale:'需更新',expired:'需更新',pending:'待复核'};
function libraryCard(lib){if(!lib)return '';const items=lib.items||[];return `<div class="card s12"><details><summary>历史研究库 · 已覆盖 ${Number(lib.coverage_count||0).toLocaleString('zh-CN')} 个证券</summary><div><div class="chips"><span class="chip">可沿用 ${Number(lib.usable_count||0).toLocaleString('zh-CN')}</span><span class="chip">需更新 ${Number(lib.stale_count||0).toLocaleString('zh-CN')}</span></div><div class="notice warn">历史研究用于复用事实与论点；旧买卖价不是当前可执行价。形成当期方案前仍需重新扫描和讨论。</div>${items.length?`<div class="scroll"><table><thead><tr><th>证券</th><th>最近复核</th><th>复用状态</th><th>研究摘要</th></tr></thead><tbody>${items.map(x=>`<tr><td><b>${esc(x.symbol)}</b><div class="name">${esc(x.name||'')}</div></td><td>${time(x.last_reviewed_at)}</td><td>${esc(LIBSTATUS[x.status]||x.status||'待复核')}</td><td>${esc(x.summary||'暂无摘要')}</td></tr>`).join('')}</tbody></table></div>`:empty('研究库尚无覆盖','运行扩展研究后，可复用的证券研究会显示在这里。')}</div></details></div>`}
const METRICLABEL={sample_count:'样本数',days:'验证天数',trading_days:'交易日数',win_rate:'胜率',hit_rate:'命中率',average_return:'平均收益',avg_return:'平均收益',median_return:'收益中位数',max_drawdown:'最大回撤',fee_cny:'费用',fees_cny:'费用',fee_bps:'费用假设',turnover:'换手',stability:'稳定性',stability_score:'稳定性评分'};
function metricText(k,v){if(v==null)return '—';if(typeof v==='object')return readable(v);if(k.endsWith('_cny'))return money(v);if(k.endsWith('_bps'))return `${Number(v).toLocaleString('zh-CN')} bp`;return typeof v==='number'?Number(v).toLocaleString('zh-CN',{maximumFractionDigits:4}):String(v)}
function returnText(v){return v==null?'—':`${Number(v)>=0?'+':''}${(Number(v)*100).toFixed(2)}%`}
function experimentSummary(e){if(typeof e.summary==='string')return esc(e.summary);const s=e.summary||{};if(s.net_return_mean!=null)return `完成 ${Number(e.sample_count??s.sample_count??0).toLocaleString('zh-CN')} 笔样本，平均净收益 <b class="${Number(s.net_return_mean)>=0?'good':'badtext'}">${returnText(s.net_return_mean)}</b>，正收益 ${Number(s.positive_samples||0)} 笔、负收益 ${Number(s.negative_samples||0)} 笔。`;return ''}
function sensitivity(e){const xs=e.threshold_sensitivity||[];if(!xs.length)return '';const names={looser:'宽松阈值',stricter:'严格阈值'};return `<h3>宽严阈值敏感性</h3><div class="scenario">${xs.map(x=>`<div><b>${names[x.label]||esc(x.label)}</b><div>样本 ${Number(x.sample_count||0)} 笔</div><div>平均净收益 ${returnText((x.summary||{}).net_return_mean)}</div><div class="muted">最差 ${returnText((x.summary||{}).worst_net_return)}</div></div>`).join('')}</div>`}
function stability(e){const xs=e.temporal_stability_observation||[];if(!xs.length)return '';const names={early_half:'前半段',late_half:'后半段'};return `<h3>时间稳定性</h3><div class="scenario">${xs.map(x=>`<div><b>${names[x.period]||esc(x.period)}</b><div>${Number(x.sample_count||0)} 笔 · 平均 ${returnText(x.mean_net_return)}</div><div class="muted">最差 ${returnText(x.worst_net_return)}</div></div>`).join('')}</div>`}
function experimentCard(e){if(!e)return `<div class="card s12"><div class="cardhead"><h2>扩展研究与历史验证</h2><span class="pill">尚未运行</span></div>${empty('还没有实验结果','此动作不会自动运行。需要时点击顶部扩展研究按钮。')}</div>`;const kind=e.kind||e.experiment_type,summary=e.summary||{},fallback={sample_count:e.sample_count,minimum_samples:e.minimum_samples,requested_lookback_trade_days:e.requested_lookback_trade_days,net_return_mean:summary.net_return_mean,worst_net_return:summary.worst_net_return},metrics=Object.keys(e.metrics||{}).length?e.metrics:Object.fromEntries(Object.entries(fallback).filter(([,v])=>v!=null)),ms=Object.entries(metrics),retrospective=kind==='selected_today_retrospective',warnings=(e.warnings||[]).length?e.warnings:(e.errors||[]);return `<div class="card s12"><div class="cardhead"><div><h2>扩展研究与历史验证</h2><div class="muted">数据截至 ${time(e.as_of_time||e.completed_at||e.retrieved_at)}</div></div>${statusPill(e.status)}</div>${retrospective?'<div class="notice warn"><b>今日候选历史回看，不是当时选股回测。</b> 结果只描述今天候选在历史区间的表现，不能代表策略当时能够选中它们。</div>':''}<p>${experimentSummary(e)}</p>${ms.length?`<div class="grid">${ms.map(([k,v])=>`<div class="card s3"><div class="label">${esc(METRICLABEL[k]||({minimum_samples:'最低样本要求',requested_lookback_trade_days:'回看交易日',net_return_mean:'平均净收益',worst_net_return:'最差净收益'}[k]||k))}</div><div class="metric">${esc(k.includes('return')?returnText(v):metricText(k,v))}</div></div>`).join('')}</div>`:'<div class="notice">本次尚无可报告指标，不显示推算胜率。</div>'}${e.sample_count!=null&&e.minimum_samples!=null&&e.sample_count<e.minimum_samples?`<div class="notice warn">有效样本 ${Number(e.sample_count)} 笔，低于最低要求 ${Number(e.minimum_samples)} 笔；结论仅供观察，不能确认稳定盈利。</div>`:''}${sensitivity(e)}${stability(e)}${warnings.length?`<div class="notice warn">${esc(warnings.map(x=>term(typeof x==='object'?readable(x):x)).join('；'))}</div>`:''}<details><summary>研究样本与分轮结果</summary><div><div><b>研究证券：</b>${(e.research_symbols||[]).length?esc(e.research_symbols.join('、')):'样本不足或尚未返回证券'}</div>${(e.rounds||[]).length?list(e.rounds):'<div class="muted">暂无分轮结果；样本不足时不生成统计结论。</div>'}</div></details></div>`}
function refreshCard(r){if(S.id!=='closing'||!r)return '';const checks=r.checks||[];return `<div class="card s12"><div class="cardhead"><div><h2>尾盘快速复核</h2><div class="muted">检查时间 ${time(r.checked_at)}</div></div><span class="pill ${r.errors&&r.errors.length?'bad':'ok'}">${r.errors&&r.errors.length?'部分失败':'复核完成'}</span></div>${checks.length?`<div class="scroll"><table><thead><tr><th>标的</th><th>信号</th><th>关键指标</th><th>阻碍</th></tr></thead><tbody>${checks.map(c=>`<tr><td><b>${esc(c.symbol)}</b><div class="name">${esc(c.name||'')}</div></td><td>${c.signal_confirmed?'<span class="pill ok">仍确认</span>':'<span class="pill bad">不再确认</span>'}</td><td>${esc(readable(c.metrics||{}))}</td><td>${(c.blockers||[]).length?esc(c.blockers.map(readable).join('；')):'—'}</td></tr>`).join('')}</tbody></table></div>`:empty('暂无可复核标的','先完成尾盘候选扫描。')}${r.errors&&r.errors.length?`<details><summary>复核错误</summary><div>${list(r.errors)}</div></details>`:''}</div>`}
function latestDataTime(d){return [d.scan?.as_of_time,d.analysis?.as_of_time,d.refresh?.as_of_time||d.refresh?.checked_at,d.experiment?.as_of_time].filter(x=>x&&Number.isFinite(Date.parse(x))).sort((a,b)=>Date.parse(b)-Date.parse(a))[0]}
function strategyCard(d){const p=d.research_policy||{};if(S.id!=='etf'||p.sector_allocation_objective!=='high_prosperity_growth')return '';const frozen=d.scan?.policy||{},changed=frozen.sector_allocation_objective!==p.sector_allocation_objective||String(frozen.sector_target_weight)!==String(p.sector_target_weight)||JSON.stringify(frozen.excluded_equity_regions||[])!==JSON.stringify(p.excluded_equity_regions||[]);return `<div class="card s12"><h2>高景气行业配置目标</h2><p>行业 ETF 合计以账户 ${pct(p.sector_target_weight)} 为讨论参考，依景气、估值和共同风险动态增减；不是强制最低仓位或已批准配置。</p><p>主动比较不同盈利驱动的行业，给出具体权重、加减仓和失效条件。${(p.excluded_equity_regions||[]).includes('hong_kong')?'当前不新增港股配置。':''}禁止债券及货币类 ETF。</p>${changed?'<div class="notice warn">目标已更新：请先重新扫描再开始 Agent 讨论。下方历史方案尚未按新目标重审。</div>':''}</div>`}
function render(d){S.detail=d;const m=d.module||{};$('#title').textContent=m.title||'投资模块';$('#subtitle').textContent=m.subtitle||'每次运行均由你手动启动';$('#asof').textContent='数据时点：'+time(latestDataTime(d));$('#quickBtn').classList.toggle('hidden',S.id!=='closing');$('#experimentBtn').textContent=S.id==='closing'?'多日历史验证':'扩展研究（下一批）';$('#workspace').innerHTML=accountCards(d)+strategyCard(d)+taskCard(d.task,d)+accountEditor(d)+libraryCard(d.library)+experimentCard(d.experiment)+refreshCard(d.refresh)+scanCard(d.scan)+agentsCard(d.analysis)+supplementalCard(d.analysis)+decisionCard(d.analysis)+(d.analysis&&d.analysis.execution&&d.analysis.execution.blockers&&d.analysis.execution.blockers.length?`<div class="card s12"><div class="notice warn"><b>执行受阻：</b>${esc(d.analysis.execution.blockers.map(readable).join('；'))}</div></div>`:'');const save=$('#saveAccount');if(save)save.onclick=saveAccount;const add=$('#addPosition');if(add)add.onclick=()=>$('#positionRows').insertAdjacentHTML('beforeend',positionRow());setButtons(moduleBusy(d));managePoll(moduleBusy(d))}
function setButtons(busy){$('#scanBtn').disabled=!!busy;$('#analyzeBtn').disabled=!!busy;$('#quickBtn').disabled=!!busy;$('#experimentBtn').disabled=!!busy}
function managePoll(busy){if(busy&&!S.poll)S.poll=setInterval(()=>load(false),2500);if(!busy&&S.poll){clearInterval(S.poll);S.poll=null}}
async function load(show=true){if(show)$('#error').classList.add('hidden');try{render(await api('/api/modules/'+S.id))}catch(e){$('#error').textContent=e.message+'。请确认本地服务已启动后重试。';$('#error').classList.remove('hidden');if(show)$('#workspace').innerHTML=`<div class="card s12">${empty('模块读取失败','页面没有使用演示数据。请检查服务状态，然后点击“刷新状态”。')}</div>`}}
async function start(action){setButtons(true);try{const path=action==='refresh'?'/api/modules/closing/refresh':`/api/modules/${S.id}/${action}`;await api(path,{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});toast(action==='analyze'?'讨论任务已启动':action==='experiment'?'扩展研究任务已启动':action==='refresh'?'快速复核已启动':'扫描任务已启动');await load(false)}catch(e){toast(e.message);await load(false)}}
async function saveAccount(){const cashRaw=$('#cash').value.trim();if(cashRaw===''){toast('请填写券商可用现金');$('#cash').focus();return}const cash=Number(cashRaw);if(!Number.isFinite(cash)||cash<0){toast('可用现金必须是非负数字');return}const positions=[...document.querySelectorAll('[data-position]')].map(row=>{const get=k=>row.querySelector(`[data-field="${k}"]`).value.trim();return {symbol:get('symbol'),name:get('name'),quantity:Number(get('quantity')||0),available_quantity:Number(get('available_quantity')||0),cost_price:Number(get('cost_price')||0)}});if(positions.some(p=>!p.symbol)){toast('每条持仓都必须填写 ETF 代码，空行请删除');return}const text=`请核对：这是券商账户事实，不是 10 万元规划资金。\n可用现金：${money(cash)}\n持仓：${positions.length} 项（将完整保存）`;if(!confirm(text))return;try{await api('/api/modules/etf/account',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({cash,positions,confirmed:true})});toast('账户事实已保存');await load(false)}catch(e){toast(e.message)}}
function candidateFacts(c){const m=c.metrics||{},facts=[['基金规模',m.fund_scale_cny??m.scale_cny??m.aum_cny,'money'],['成交额',m.turnover_cny??m.amount_cny,'money'],['上市日期',m.listing_date??m.listed_at],['跟踪指数',m.tracking_index_name??m.tracking_index],['日均成交额',m.average_turnover_cny??m.avg_turnover_cny,'money'],['数据日期',m.as_of_date??c.as_of_date]];const rows=facts.filter(([,v])=>v!=null&&v!=='').map(([k,v,t])=>`<tr><th>${k}</th><td>${t==='money'?money(v):esc(v)}</td></tr>`).join('');return rows?`<table><tbody>${rows}</tbody></table>`:'<span class="muted">未提供额外规模或日期事实</span>'}
function showCandidate(i){const c=S.detail.scan.candidates[i],conditions=c.execution_conditions||c.conditions||[];$('#rawBody').innerHTML=`<h3>${esc(c.symbol)} ${esc(c.name||'')}</h3><h3>关键事实</h3>${candidateFacts(c)}<h3>入选理由</h3>${list(c.reasons)}<h3>主要风险</h3>${list(c.risks)}<h3>执行条件</h3>${list(Array.isArray(conditions)?conditions:[conditions],'未给出额外执行条件')}<h3>证据缺口</h3>${list(c.evidence_gaps,'未标记证据缺口')}<details><summary>全部指标</summary><div class="detailraw">${esc(JSON.stringify(c.metrics||{},null,2))}</div></details>${c.sources?`<h3>候选来源</h3>${sources(c.sources)}`:''}`;$('#rawDialog').showModal()}
function showAgent(i){const a=S.detail.analysis.research[i];$('#rawBody').innerHTML=`<h3>${esc(a.display_name||a.agent_id)}</h3><p>${esc(a.summary||'')}</p><div class="detailraw">${esc(JSON.stringify(a,null,2))}</div>`;$('#rawDialog').showModal()}
document.querySelectorAll('.navbtn').forEach(b=>b.onclick=()=>{document.querySelectorAll('.navbtn').forEach(x=>x.classList.remove('active'));b.classList.add('active');S.id=b.dataset.module;if(S.poll){clearInterval(S.poll);S.poll=null}load()});
$('#refreshBtn').onclick=()=>load();$('#scanBtn').onclick=()=>start('scan');$('#analyzeBtn').onclick=()=>start('analyze');$('#quickBtn').onclick=()=>start('refresh');$('#experimentBtn').onclick=()=>start('experiment');load();
</script></body></html>"""
